(function(root){'use strict';
const portraits=[{id:'akira',name:'Akira',title:'Ember Guardian',world:'The Sunfall Kingdom',asset:'assets/portraits/akira.webp',accent:'amber',motto:'Carry the light. Write your own story.',age:28},{id:'luna',name:'Luna',title:'Moonlit Dreamer',world:'Moonflower Valley',asset:'assets/portraits/luna.webp',accent:'lilac',motto:'A little wonder, wherever you wander.',age:30},{id:'ren',name:'Ren',title:'Neon Voyager',world:'New Hikari',asset:'assets/portraits/ren.webp',accent:'aqua',motto:'Find yourself beyond the familiar.',age:30}];
const accents={amber:'#f0bc82',lilac:'#c4b0ec',aqua:'#93dce0',rose:'#e6a8bc'};
const defaults={portrait:'akira',name:'Akira',title:'Ember Guardian',motto:'Carry the light. Write your own story.',layout:'cinema',light:'natural',accent:'amber',zoom:100,crop:35};
function text(value,fallback,max){if(typeof value!=='string')return fallback;return Array.from(value.replace(/[\u0000-\u001f\u007f]/g,'').trim()).slice(0,max).join('')||fallback}
function clean(raw={}){if(!raw||typeof raw!=='object')raw={};const p=portraits.find(p=>p.id===raw.portrait)||portraits[0];let n=(v,f,min,max)=>Number.isFinite(Number(v))&&v!==null&&v!==''?Math.round(Math.min(max,Math.max(min,Number(v)))):f;return {portrait:p.id,name:text(raw.name,p.name,24),title:text(raw.title,p.title,40),motto:text(raw.motto,p.motto,65),layout:['cinema','gallery','nocturne'].includes(raw.layout)?raw.layout:'cinema',light:['natural','dusk','noir'].includes(raw.light)?raw.light:'natural',accent:Object.hasOwn(accents,raw.accent)?raw.accent:p.accent,zoom:n(raw.zoom,100,100,160),crop:n(raw.crop,35,0,100)}}
function encode(raw){return new URLSearchParams({edition:'1',...clean(raw)}).toString()}
function decode(hash){if(typeof hash!=='string'||hash.length>2048)return null;try{const p=new URLSearchParams(hash.replace(/^#/,''));if(p.get('edition')!=='1')return null;return clean(Object.fromEntries(p))}catch{return null}}
function surprise(random=Math.random){const pick=arr=>arr[Math.min(arr.length-1,Math.floor(Math.max(0,random())*arr.length))];const p=pick(portraits);return clean({...p,portrait:p.id,layout:pick(['cinema','gallery','nocturne']),light:pick(['natural','dusk']),accent:p.accent,motto:pick([p.motto,'There is a whole universe in you.','Stay curious. Become unforgettable.','The next chapter belongs to you.'])})}
const api={portraits,accents,defaults,clean,encode,decode,surprise};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.YoruPortraits=api;
})(typeof window==='undefined'?globalThis:window);
